CREATE TABLE api_tokens ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, level VARCHAR(8) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, expires_at DATETIME, blocked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE auth_sessions ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, account_id INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, ip VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE days ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, date VARCHAR(10) NOT NULL, content_enc BLOB NOT NULL, revision INTEGER NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), CONSTRAINT uq_days_user_date UNIQUE (user_id, date), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE invites ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE notes ( id INTEGER NOT NULL, uid VARCHAR(36) NOT NULL, user_id INTEGER NOT NULL, date VARCHAR(10) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME, text_enc BLOB NOT NULL, prompt_enc BLOB, photo_id VARCHAR(40), PRIMARY KEY (id), CONSTRAINT uq_notes_user_uid UNIQUE (user_id, uid), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE settings ( "key" VARCHAR(64) NOT NULL, value JSON, PRIMARY KEY ("key") );
CREATE TABLE user_keys ( user_id INTEGER NOT NULL, wrapped_dek BLOB NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (user_id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE users ( id INTEGER NOT NULL, name VARCHAR(64) NOT NULL, display_name VARCHAR(80) NOT NULL, whats_new_seen VARCHAR(32) NOT NULL, role VARCHAR(16) NOT NULL, sign_in VARCHAR(16) NOT NULL, password_hash VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, oidc_subject VARCHAR(255) NOT NULL, language VARCHAR(16) NOT NULL, profile JSON, created_at DATETIME NOT NULL, last_seen_at DATETIME, failed_logins INTEGER NOT NULL, locked_until DATETIME, blocked_at DATETIME, totp_secret_enc TEXT NOT NULL, totp_recovery TEXT NOT NULL, totp_last_step INTEGER NOT NULL, avatar BLOB, avatar_at DATETIME, values_seeded BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
CREATE TABLE value_defs ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, position INTEGER NOT NULL, data_enc BLOB NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), CONSTRAINT uq_value_defs_user_uid UNIQUE (user_id, uid), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE INDEX ix_api_tokens_account_id ON api_tokens (account_id);
CREATE INDEX ix_auth_sessions_account_id ON auth_sessions (account_id);
CREATE INDEX ix_notes_user_date ON notes (user_id, date);
CREATE INDEX ix_value_defs_user_id ON value_defs (user_id);
